        dev4online: isOnline(devices.device4),
        dev5online: isOnline(devices.device5),
        dev1name: (devices.device1 && devices.device1.friendlyName) || "Device 1",
        dev2name: (devices.device2 && devices.device2.friendlyName) || "Device 2",
        dev3name: (devices.device3 && devices.device3.friendlyName) || "Device 3",
        dev4name: (devices.device4 && devices.device4.friendlyName) || "Device 4",
        dev5name: (devices.device5 && devices.device5.friendlyName) || "Device 5",
    };

    return { payload: output };
}

// --- Initialization ---
if (!context.get('initialized')) {
    context.set('devices', {
        device1: {},
        device2: {},
        device3: {},
        device4: {},
        device5: {}
    });
    context.set('initialized', true);
}

let devices = context.get('devices');

// --- Handle device messages (from Parse Device Data) ---
let dev = devices[msg.deviceId] || {};

// Update last seen timestamp for ANY message from this device
dev.lastSeen = Date.now();

switch (msg.dataType) {
    case "lwt":
        dev.lwt = msg.value;
        break;

    case "status":
        dev.status = msg.value;
        dev.statusColor = msg.statusColor;
        break;

    case "mode":
        dev.mode = msg.value;
        dev.modeDisplay = msg.modeDisplay;
        break;

    case "active_led":
        dev.activeLed = msg.value;
        dev.ledColorCode = msg.ledColorCode;
        break;

    case "ip":
        dev.ip = msg.value;
        break;

    case "version":
        dev.version = msg.value;
        break;

    case "friendly_name":
        dev.friendlyName = msg.value;
        break;    

    case "log":
        if (!dev.logs) dev.logs = [];
        dev.logs.unshift(msg.logEntry);
        dev.logs = dev.logs.slice(0, 30);
        break;

    case "meeting":
        if (!dev.meeting) dev.meeting = {};
        dev.meeting[msg.meetingField] = msg.value;
        break;
}

devices[msg.deviceId] = dev;
