// Extract device ID and data type from topic
// Topic format: busylight/device3/status or busylight/1/meeting/title
const parts = msg.topic.split('/');
let deviceId = parts[1]; // "device3" or "1"
const dataType = parts[2]; // "status", "mode", "ip", "log", "lwt", "active_led", "meeting"

// Don't process "all" commands
if (deviceId === "all") {
    return null;
}

msg.deviceId = deviceId;
msg.dataType = dataType;
msg.value = msg.payload;

if (msg.dataType === "lwt" && msg.retain === true) {
    return null;
}

// Handle meeting subtopics (busylight/1/meeting/title)
if (dataType === 'meeting' && parts[3]) {
    msg.meetingField = parts[3];  // title, date, start, current, end
}

// Add timestamp for activity tracking
msg.timestamp = new Date().toLocaleTimeString('en-US', { timeZone: 'America/New_York' });

// Enhanced logging for certain types
if (dataType === "log") {
    msg.logEntry = `${msg.timestamp} - ${msg.payload}`;
}

// Status enrichment
if (dataType === "status") {
    msg.statusColor = getStatusColor(msg.payload);
}

// Mode enrichment
if (dataType === "mode") {
    msg.modeDisplay = formatMode(msg.payload);
}

// Connection state
if (dataType === "lwt") {
    msg.isOnline = (msg.payload === "online");
    msg.connectionStatus = msg.payload;
}

// Active LED color
if (dataType === "active_led") {
    msg.ledColor = msg.payload;
    msg.ledColorCode = getLedColorCode(msg.payload);
}

return msg;

// Helper functions
function getStatusColor(status) {
    const colors = {
        "busy": "red",
        "free": "green",
        "remote": "blue",
        "off_hours": "gray",
        "unknown": "orange"
    };
    return colors[status] || "gray";
}

function formatMode(mode) {
    return mode.replace(/_/g, " ");
}

function getLedColorCode(color) {
    const codes = {
        "RED": "#FF0000",
        "GREEN": "#00FF00",
        "BLUE": "#0000FF",
        "YELLOW": "#FFFF00",
        "WHITE": "#FFFFFF",
        "OFF": "#000000",
        "EFFECT": "#FF00FF",
        "NONE": "#808080"
    };
    return codes[color] || "#808080";
}

